INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-16', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '入蜀，以宣信中郎副費禕使吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-17', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '七年，以侍中守尚書令，為大將軍費禕副貳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-18', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '華陽國志曰：時蜀人以諸葛亮、蔣琬、費禕及允為四相，一號四英也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-19', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '多技藝，挾數術，費禕甚異之，故超繼允內侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-040-20', 'p0175', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-040-21', 'p0175', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '秋，亮病困，密與長史楊儀、司馬費禕、護軍姜維等作身歿之後退軍節度，令延斷後，姜維次之；若延或不從命，軍便自發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-040-22', 'p0175', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '時人畏其言語不節，莫敢從也，惟後軍師費禕往慰省之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-23', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '蔣琬、費禕等皆器重之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-24', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '延熈九年秋，大赦，光於衆中責大將軍費禕曰：「夫赦者，偏枯之物，非明世所宜有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-25', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '刺史費禕命為從事，入為尚書郎，復辟禕大將軍東曹掾，稍遷尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-26', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '立上言：「故蜀大官及盡忠死事者子孫，雖仕郡國，或有不才，同之齊民為劇；又諸葛亮、蔣琬、費禕等子孫流徙中畿，各宜量才叙用，以慰巴、蜀之心，傾吳人之望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-043-27', 'p0175', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '七年春，大將軍費禕北禦魏敵，留忠成都，平尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-043-28', 'p0175', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '涪諸軍及大將軍費禕自成都相繼而至，魏軍退還，如平本策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-043-29', 'p0175', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '嶷初見費禕為大將軍，恣性汎愛，待信新附太過，嶷書戒之曰：「昔岑彭率師，來歙杖節，咸見害於刺客，今明將軍位尊權重，宜鑒前事，少以為警。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-30', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '於是遣尚書令費禕、中監軍姜維等喻指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-31', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '輙與費禕等議，以涼州胡塞之要，進退有資，賊之所惜；且羌、胡乃心思漢如渴，又昔偏軍入羌，郭淮破走，筭其長短，以為事首，宜以姜維為涼州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-32', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會大將軍費禕從成都至，魏軍即退，敏以功封雲亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-33', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '費禕字文偉，江夏鄳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-34', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '十年，遷衞將軍，與大將軍費禕共錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-35', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '每欲興軍大舉，費禕常裁制不從，與其兵不過萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-36', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '漢晉春秋曰：費禕謂維曰：「吾等不如丞相亦已遠矣；丞相猶不能定中夏，況吾等乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-37', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '評曰：蔣琬方整有威重，費禕寬濟而博愛，咸承諸葛之成規，因循而不革，是以邊境無虞，邦家和一，然猶未盡治小之宜，居靜之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-045-38', 'p0175', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '先是，吳王孫權請和，先主累遣宋瑋、費禕等與相報荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-045-39', 'p0175', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」權大笑，嘉其抗直，甚愛待之，見敬亞於鄧芝、費禕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-045-40', 'p0175', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '芝性驕慠，自大將軍費禕等皆避下之，而預獨不為屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-053-41', 'p0175', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '江表傳曰：費禕聘于吳，陛見，公卿侍臣皆在坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-064-42', 'p0175', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪別傳曰：權甞饗蜀使費禕，先逆勑羣臣：「使至，伏食勿起。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-064-43', 'p0175', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '昔魏人伐蜀，蜀人禦之，精嚴垂發，六軍雲擾，士馬擐甲，羽檄交馳，費禕時為元帥，荷國任重，而與來敏圍碁，意無厭倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a05-002-44', 'p0175', 'jinshu', 'a05-002', '《晉書·卷二》', '林退，帝謂玄曰：「費禕以據險距守，進不獲戰，攻之不可，宜亟旋軍，以為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-0', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：是時姜維亦出圍狄道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-1', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '姜維有重兵而縣軍應恪，投食我麥，非深根之寇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-2', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '姜維聞淮進兵，軍食少，乃退屯隴西界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-3', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乃者蜀將姜維寇鈔脩郡，為所執略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-4', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '世語及魏氏春秋並云：此秋，姜維寇隴右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-5', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '八月辛亥，蜀大將軍姜維寇狄道，雍州刺史王經與戰洮西，經大敗，還保狄道城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-6', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸未，安西將軍鄧艾大破蜀大將姜維於上邽，詔曰：「兵未極武，醜虜摧破，斬首獲生，動以萬計，自頃戰克，無如此者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-7', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，蜀大將姜維寇洮陽，鎮西將軍鄧艾拒之，破維於侯和，維遁走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-8', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '夏五月，詔曰：「蜀，蕞爾小國，土狹民寡，而姜維虐用其衆，曾無廢志；往歲破敗之後，猶復耕種沓中，刻剥衆羌，勞役無已，民不堪命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-9', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '蜀大將軍姜維率衆依麴山築二城，使牙門將句安、李歆等守之，聚羌胡質任等寇偪諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-10', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '後年，雍州刺史王經白泰，云姜維、夏侯霸欲三道向祁山、石營、金城，求進兵為翅，使涼州軍至枹，討蜀護軍向祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-11', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '姜維之兵，是所辟之鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-12', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」泰曰：「姜維提輕兵深入，正欲與我爭鋒原野，求一戰之利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-026-13', 'p0176', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '姜維出石營，從彊川，乃西迎治無戴，留陰平太守廖化於成重山築城，斂破羌保質。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-027-14', 'p0176', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '姜維因洮上之利，輕兵深入，糧餉不繼，軍覆上邽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-027-15', 'p0176', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '姜維深入，不待輜重，士衆飢餓，覆軍上邽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-16', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '嘉平元年，與征西將軍郭淮拒蜀偏將軍姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-17', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '解雍州刺史王經圍於狄道，姜維退駐鍾提，乃以艾為安西將軍，假節、領護東羌校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-18', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '甘露元年詔曰：「逆賊姜維連年狡黠，民夷騷動，西土不寧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-19', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」二年，拒姜維於長城，維退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-20', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」又曰：「姜維自一時雄兒也，與某相值，故窮耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-21', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '昔姜維有斷隴右之志，艾脩治備守，積糓彊兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-22', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文王以蜀大將姜維屢擾邊陲，料蜀國小民疲，資力單竭，欲大舉圖蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-23', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '姜維自沓中還，至陰平，合集士衆，欲赴關城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-24', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾追姜維到陰平，簡選精銳，欲從漢德陽入江由、左儋道詣緜竹，趣成都，與諸葛緒共行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-25', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '緒以本受節度邀姜維，西行非本詔，遂進軍前向白水，與會合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-26', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-27', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　漢晉春秋曰：初，夏侯霸降蜀，姜維問之曰：「司馬懿旣得彼政，當復有征伐之志不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-28', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欲使姜維等皆將蜀兵出斜谷，會自將大衆隨其後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-29', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '時方給與姜維鎧杖，白外有匈匈聲，似失火，有頃，白兵走向城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-30', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '姜維率會左右戰，手殺五六人，衆旣格斬維，爭赴殺會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-31', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '五年春正月，監軍姜維督偏軍，自漢中還屯涪縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-32', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十年，涼州胡王白虎文、治無戴等率衆降，衞將軍姜維迎逆安撫，居之于繁縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-33', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '秋，衞將軍姜維出攻雍州，不克而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-34', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十三年，姜維復出西平，不克而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-35', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '夏四月，衞將軍姜維復率衆圍南安，不克而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-36', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十七年春正月，姜維還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-37', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十八年春，姜維還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-38', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十九年春，進姜維位為大將軍，督戎馬，與鎮西將軍胡濟期會上邽，濟失誓不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-39', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '二十年，聞魏大將軍諸葛誕據壽春以叛，姜維復率衆出駱谷，至芒水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-40', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '景耀元年，姜維還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-41', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，姜維復率衆出侯和，為鄧艾所破，還住沓中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-42', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '」禪又遣太常張峻、益州別駕汝超受節度，遣太僕蔣顯有命勑姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-43', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '雖使諸葛亮在，不能輔之乆全，而況姜維邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-44', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮拔西縣千餘家，還于漢中，郭沖四事曰：亮出祁山，隴西、南安二郡應時降，圍天水，拔兾城，虜姜維，驅略士女數千人還蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-45', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '姜維，天水之匹夫耳，獲之則於魏何損？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-46', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '姜維謂亮曰：「辛佐治仗節而到，賊不復出矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-47', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '姜維令儀反旗鳴鼓，若將向宣王者，宣王乃退，不敢偪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-48', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '自瞻、厥、建統事，姜維常征伐在外，宦人黃皓竊弄機柄，咸共將護，無能匡矯，孫盛異同記曰：瞻、厥等以維好戰無功，國內疲弊，宜表後主，召還為益州刺史，奪其兵權；蜀長老猶有瞻表以閻宇代維故事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-036-49', 'p0176', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」大將軍姜維等議，以為雲昔從先帝，勞績旣著，經營天下，遵奉法度，功效可書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-036-50', 'p0176', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '次子廣，牙門將，隨姜維沓中，臨陣戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-039-51', 'p0176', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂卒，祗又以侍中守尚書令，加鎮軍將軍，大將軍姜維雖班在祗上，常率衆在外，希親朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-040-52', 'p0176', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」後監軍姜維率偏軍經汶山，往詣立，稱立意氣不衰，言論自若。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-040-53', 'p0176', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-040-54', 'p0176', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '秋，亮病困，密與長史楊儀、司馬費禕、護軍姜維等作身歿之後退軍節度，令延斷後，姜維次之；若延或不從命，軍便自發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-042-55', 'p0176', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '子忠，亦博覽經學，有敏風，與尚書向充等並能協贊大將軍姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-043-56', 'p0176', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '魏狄道長李簡密書請降，衞將軍姜維率嶷等因簡之資以出隴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-043-57', 'p0176', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '姜維之出，時論以嶷初還，股疾不能在行中，由是嶷自乞肆力中原，致身敵庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-58', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '於是遣尚書令費禕、中監軍姜維等喻指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-59', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '輙與費禕等議，以涼州胡塞之要，進退有資，賊之所惜；且羌、胡乃心思漢如渴，又昔偏軍入羌，郭淮破走，筭其長短，以為事首，宜以姜維為涼州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-60', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '姜維字伯約，天水兾人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-61', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」孫盛雜記曰：初，姜維詣亮，與母相失，復得母書，令求當歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-62', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」　孫盛晉陽秋曰：盛以永和初從安西將軍平蜀，見諸故老，及姜維旣降之後密與劉禪表疏，說欲偽服事鍾會，因殺之以復蜀土，會事不捷，遂至泯滅，蜀人于今傷之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-63', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '盛以為古人云，非所困而困焉名必辱，非所據而據焉身必危，旣辱且危，死其將至，其姜維之謂乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-64', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '凡人之談，常譽成毀敗，扶高抑下，咸以姜維投厝無所，身死宗滅，以是貶削，不復料擿，異乎春秋襃貶之義矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-65', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '如姜維之樂學不倦，清素節約，自一時之儀表也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-66', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '姜維策名魏室，而外奔蜀朝，違君徇利，不可謂忠；捐親苟免，不可謂孝；害加舊邦，不可謂義；敗不死難，不可謂節；且德政未敷而疲民以逞，居禦侮之任而致敵喪守，於夫智勇，莫可云也：凡斯六者，維無一焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-67', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '姜維粗有文武，志立功名，而翫衆黷旅，明斷不周，終致隕斃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-68', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '干寶曰：姜維為蜀相，國亡主辱弗之死，而死於鍾會之亂，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-69', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '於時人少所敬貴，唯器異姜維云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-70', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '十八年，與衞將軍姜維俱還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-71', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '漢晉春秋曰：景耀五年，姜維率衆出狄道，廖化曰：「『兵不戢，必自焚』，伯約之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-72', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '延熈二十年，隨大將軍姜維出軍至芒水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-73', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '大將軍姜維每出北征，羌、胡出馬牛羊氈毦及義穀裨軍糧，國賴其資。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-74', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-064-75', 'p0176', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '漢晉春秋曰：恪使司馬季無往蜀說姜維，令同舉，曰：「古人有言，聖人不能為時，時至亦不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-001-76', 'p0176', 'jinshu', 'a05-001', '《晉書·卷一》', '初，蜀將姜維聞毗來，謂亮曰：「辛毗杖節而至，賊不復出矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-77', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '蜀將姜維之寇隴右也，征西將軍郭淮自長安距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-78', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '蜀將姜維又寇隴右，揚聲欲攻狄道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-79', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '雍州刺史陳泰欲先賊據狄道，帝曰：「姜維攻羌，收其質任，聚穀作邸閣訖，而復轉行至此，正欲了塞外諸羌，為後年之資耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-80', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '今絆姜維於沓中，使不得東顧，直指駱谷，出其空虛之地，以襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-81', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '於是徵四方之兵十八萬，使鄧艾自狄道攻姜維於沓中，雍州刺史諸葛緒自祁山軍于武街，絕維歸路，鎮西將軍鍾會帥前將軍李輔、征蜀護軍胡烈等自駱谷襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-82', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '姜維聞之，引還，王頎追敗維於強川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-013-83', 'p0176', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀將姜維攻隴西，車騎將軍郭淮討破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-037-84', 'p0176', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '及蜀將姜維寇隴右，雍州刺史王經戰敗，遣孚西鎮關中，統諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-037-85', 'p0176', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '先是蜀將姜維屢寇關中，及望至，廣設方略，維不得爲寇，關中賴之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-033-0', 'p0177', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '遣尚書郎鄧芝固好於吳，吳王孫權與蜀和親使聘，是歲通好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-033-1', 'p0177', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '秋，涪陵屬國民夷反，車騎將軍鄧芝往討，皆破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-035-2', 'p0177', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '六年春，揚聲由斜谷道取郿，使趙雲、鄧芝為疑軍，據箕谷，魏大將軍曹真舉衆拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-036-3', 'p0177', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '亮令雲與鄧芝往拒，而身攻祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-040-4', 'p0177', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-041-5', 'p0177', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '會先主薨，諸葛亮遣鄧芝使吳，亮令芝言次可從權請裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-043-6', 'p0177', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '是時，鄧芝在東，馬忠在南，平在北境，咸著名迹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-7', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '鄧芝字伯苗，義陽新野人，漢司徒禹之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-8', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '陰化不盡；和合二國，唯有鄧芝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-9', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」權大笑，嘉其抗直，甚愛待之，見敬亞於鄧芝、費禕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-10', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時車騎將軍鄧芝自江州還，來朝，謂預曰：「禮，六十不服戎，而卿甫受兵，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-11', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-047-12', 'p0177', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十一月，蜀使中郎將鄧芝來聘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-047-13', 'p0177', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」　吳錄曰：是歲蜀主又遣鄧芝來聘，重結盟好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-035-0', 'p0178', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '權問諸葛恪曰：「樊建何如宗預也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-045-1', 'p0178', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '宗預字德豔，南陽安衆人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-045-2', 'p0178', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '官位與張翼齊，而在宗預之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-045-3', 'p0178', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0179-a04-044-0', 'p0179', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '東曹掾楊戲素性簡略，琬與言論，時不應荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0179-a04-045-1', 'p0179', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '楊戲字文然，犍為武陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0179-a04-045-2', 'p0179', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '楊戲商略，意在不羣，然智度有短，殆罹世難云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a03-083-0', 'p0180', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '」字之曰德曜，名孟光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a03-084-1', 'p0180', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '君若欲慕鮑宣、梁鴻之高者，妾亦請從少君、孟光之事矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-032-2', 'p0180', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣等謹與博士許慈、議郎孟光建立禮儀，擇令辰，上尊號。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-042-3', 'p0180', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '先主定蜀，承喪亂歷紀，學業衰廢，乃鳩合典籍，沙汰衆學，慈、潛並為博士，與孟光、來敏等典掌舊文。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-042-4', 'p0180', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '孟光字孝裕，河南洛陽人，漢太尉孟郁之族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-042-5', 'p0180', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '時孟光亦以樞機不慎，議論干時，然猶愈於敏，俱以其耆宿學士見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-0', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '先主定蜀，承喪亂歷紀，學業衰廢，乃鳩合典籍，沙汰衆學，慈、潛並為博士，與孟光、來敏等典掌舊文。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-1', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '好公羊春秋而譏呵左氏，每與來敏爭此二義，光常譊譊讙咋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-2', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '來敏字敬達，義陽新野人，來歙之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-3', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '亮集有教曰：「將軍來敏對上官顯言『新人有何功德而奪我榮資與之邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-4', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '昔成都初定，議者以為來敏亂羣，先帝以新定之際，故遂含容，無所禮用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-044-5', 'p0181', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '光祿大夫來敏至禕許別，求共圍棊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-064-6', 'p0181', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '昔魏人伐蜀，蜀人禦之，精嚴垂發，六軍雲擾，士馬擐甲，羽檄交馳，費禕時為元帥，荷國任重，而與來敏圍碁，意無厭倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-032-0', 'p0182', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-042-1', 'p0182', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '尹默字思潛，梓潼涪人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-042-2', 'p0182', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '父仁，字德賢，與同縣尹默俱游荊州，從司馬徽、宋忠等學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-042-3', 'p0182', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '許、孟、來、李，愽涉多聞，尹默精於左氏，雖不以德業為稱，信皆一時之學士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0183-a04-050-0', 'p0183', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '奮弟祺，吳書曰：祺與張溫、顧譚友善，權令關平辭訟事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0185-a03-072-0', 'p0185', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遂引兵攻傕，矢及帝前，獻帝紀曰：「汜與傕將張苞、張龍謀誅傕，汜將兵夜攻傕門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0185-a04-026-1', 'p0185', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '縣人張苞為郡督郵，貪穢受取，干亂吏政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0187-a04-040-0', 'p0187', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '儀遣馬岱追斬之，致首於儀，儀起自踏之，曰：「庸奴！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0187-a05-001-1', 'p0187', 'jinshu', 'a05-001', '《晉書·卷一》', '蜀將馬岱入寇，帝遣將軍牛金擊走之，斬千餘級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-004-0', 'p0188', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '興移書日南州郡，開示大計，兵臨合浦，告以禍福；遣都尉唐譜等詣進乘縣，因南中都督護軍霍弋上表自陳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-041-1', 'p0188', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '漢晉春秋曰：霍弋聞魏軍來，弋欲赴成都，後主以備敵旣定，不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-042-2', 'p0188', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時羅憲以重兵據白帝，霍弋以彊卒鎮夜郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-048-3', 'p0188', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '漢晉春秋曰：初霍弋遣楊稷、毛炅等戍，與之誓曰：「若賊圍城，未百日而降者，家屬誅；若過百日而城沒者，刺史受其罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-048-4', 'p0188', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳人並諫，璜曰：「霍弋已死，無能來者，可須其糧盡，然後乃受，使彼來無罪，而我取有義，內訓吾民，外懷鄰國，不亦可乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a05-015-5', 'p0188', 'jinshu', 'a05-015', '《晉書·卷十五》', '晉平蜀，以蜀建寧太守霍弋遙領交州，得以便宜選用長吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-041-0', 'p0189', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '弋與巴東領軍襄陽羅憲各保全一方，舉以內附，咸因仍前任，寵待有加。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-041-1', 'p0189', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '襄陽記曰：羅憲字令則。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-042-2', 'p0189', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時羅憲以重兵據白帝，霍弋以彊卒鎮夜郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-048-3', 'p0189', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二月，鎮軍陸抗、撫軍步恊、征西將軍留平、建平太守盛曼，率衆圍蜀巴東守將羅憲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-048-4', 'p0189', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '魏使將軍胡烈步騎二萬侵西陵，以救羅憲，陸抗等引軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-008-full-0', 'p0190', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '寇桂陽，長沙太守孫堅擊斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-008-1', 'p0190', 'houhanshu', 'a03-008', '《後漢書·卷八》', '寇桂陽，長沙太守孫堅擊斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-2', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '孫堅殺荊州刺史王叡，王氏譜曰：「叡字通曜，晉太保祥伯父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-3', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-4', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅攻劉表於襄陽，堅戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-5', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-048-6', 'p0190', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '孫堅從桂陽入雒討董卓，軍於城南，見井中有五色光，軍人莫敢汲，堅乃浚得璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-7', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '溫參軍事孫堅說慎曰：堅字文臺，吳郡富春人，即孫權之父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-8', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時長沙太守孫堅亦率豫州諸郡兵討卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-9', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '明年，孫堅收合散卒，進屯梁縣之陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-10', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '唯孫堅小戇，說文曰：「戇，愚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-11', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時孫堅為溫參軍，勸溫陳兵斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-073-12', 'p0190', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '術遣越隨其將孫堅，擊袁紹將周昕，越為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-073-13', 'p0190', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '又長沙太守孫堅，前領豫州刺史，遂能驅走董卓，埽除陵廟，忠勤王室，其功莫大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-14', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '會長沙太守孫堅殺南陽太守張咨，英雄記曰：「咨字子議，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-15', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」吳曆曰：「孫堅至南陽，咨不給軍糧，又不肯見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-16', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '初平三年，術遣孫堅擊劉表於襄陽，堅戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-17', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '又聞孫堅得傳國璽，韋昭吳書曰：「漢室大亂，天子北詣河上，六璽不自隨，掌璽者以投井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-18', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫堅北討董卓，頓軍城南，甄官署有井，每旦有五色氣從井中出，使人浚井，得漢傳國玉璽，其文曰『受命于天，旣壽永昌』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-19', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '自孫堅死，子策復領其部曲，術遣擊楊州刺史劉繇，破之，策因據江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-120-20', 'p0190', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '孫堅北討董卓，頓軍城南，官署有井，每旦有五色氣從井出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-001-21', 'p0190', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-006-22', 'p0190', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會長沙太守孫堅殺南陽太守張咨，術得據其郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-006-23', 'p0190', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術之在南陽也，與孫堅合從，欲襲奪表州，使堅攻表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-008-24', 'p0190', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '是時，術遣孫堅屯陽城拒卓，紹使周昂奪其處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-008-25', 'p0190', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '又長沙太守孫堅，前領豫州刺史，驅走董卓，掃除陵廟，其功莫大；紹令周昂盜居其位，斷絕堅糧，令不得入，使卓不被誅，紹罪十也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-022-26', 'p0190', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '太守孫堅舉階孝廉，除尚書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-028-27', 'p0190', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：黃初末，吳人發長沙王吳芮冢，以其塼於臨湘為孫堅立廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-031-28', 'p0190', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '臣松之案：靈帝崩後，義軍起，孫堅殺荊州刺史王叡，然後劉表為荊州，不與焉同時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-039-29', 'p0190', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '時孫堅舉兵討董卓，以南陽太守張咨不給軍糧，殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-039-30', 'p0190', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之案：劉焉在漢靈帝時已經宗正太常，出為益州牧，祥始以孫堅作長沙時為江夏太守，不得舉焉為孝廉，明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-31', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫堅字文臺，吳郡富春人，蓋孫武之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-32', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '惟孫堅小戇，頗能用人，當語諸將，使知忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-33', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時又上章言狀，而孫堅隨周慎行，謂慎求將萬兵造金城，使慎以二萬作後駐，邊、韓城中無宿穀，當於外運，畏慎大兵，不敢輕與堅戰，而堅兵足以斷其運道，兒曹用必還羌谷中，涼州或能定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-34', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」卓曰：「然，但殺二袁、劉表、孫堅，天下自服從孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-35', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣松之以為孫堅於興義之中最有忠烈之稱，若得漢神器而潛匿不言，此為陰懷異志，豈所謂忠臣者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-36', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」　臣松之案：本傳云孫堅以初平三年卒，策以建安五年卒，策死時年二十六，計堅之亡，策應十八，而此表云十七，則為不符。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-37', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '評曰：孫堅勇摯剛毅，孤微發迹，導溫戮卓，山陵杜塞，有忠壯之烈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-050-38', 'p0190', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫堅聞其才貌，欲娶之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-051-39', 'p0190', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '且孫堅以初平二年卒，洞口之役在黃初三年，堅卒至此合三十一年，匡時若尚在，本傳不得云卒時年二十餘也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-054-40', 'p0190', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，孫堅興義兵討董卓，徙家於舒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-055-41', 'p0190', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從孫堅征伐，討黃巾於宛、鄧，破董卓於陽人，攻城野戰，身被創夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-055-42', 'p0190', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '以便弓馬，有膂力，幸於孫堅，從征伐周旋，數犯危難，陷敵擒虜，為別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-056-43', 'p0190', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '初為縣吏，後察孝廉，州辟從事，隨孫堅征伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-061-44', 'p0190', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '父祉，字宣嗣，從孫堅征伐有功，堅薦祉為九江太守，後轉吳郡，所在有聲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-064-45', 'p0190', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻字子遠，孫堅弟靜之曾孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-0', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-1', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '繇軍敗績，孫策遂據江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-2', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '吳志曰：「孫策旣破繇，遂度兵據會稽，策自領會稽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-3', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，孫策死，為許貢客所射傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-031-4', 'p0191', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '術大怒，遣其將孫策攻康，圍城數重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-045-5', 'p0191', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '後孫策破會稽，忠等浮海南投交阯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-068-6', 'p0191', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '及孫策平吳，劭與繇南奔豫章而卒，時年四十六。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-070-7', 'p0191', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '後為孫策廬江太守李術所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-075-8', 'p0191', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '魏志曰「勳字子臺，琅邪人，與太祖有舊，為孫策破後，自歸太祖，封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-075-9', 'p0191', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫策破勳，復見收視，術女入孫權宮，子曜仕吳為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-076-10', 'p0191', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '袁術遣孫策攻破繇，因奔豫章，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-112-11', 'p0191', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '」　新淦　宜春　廬陵興平元年，孫策分立廬陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-001-12', 'p0191', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是歲，孫策受袁術使渡江，數年閒遂有江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-001-13', 'p0191', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫策聞公與紹相持，乃謀襲許，未發，為刺客所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-006-14', 'p0191', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '妻子依術故吏廬江太守劉勳，孫策破勳，復見收視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-007-15', 'p0191', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '孫策遣軍攻登於匡琦城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-010-16', 'p0191', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '建安五年，為孫策廬江太守李術所殺，時年三十八。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-012-17', 'p0191', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '避難江東，孫策禮命之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-012-18', 'p0191', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '後為廬江太守，為孫策所破，自歸太祖，封列侯，遂從在散伍議中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-19', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孫策略地江東，歆知策善用兵，乃幅巾奉迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-20', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '胡冲吳歷曰：孫策擊豫章，先遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-21', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '華嶠譜叙曰：孫策略有揚州，盛兵徇豫章，一郡大恐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-22', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '虞溥江表傳曰：孫策在椒丘，遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-23', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '獻帝春秋曰：孫策率軍如閩、越討朗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-24', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」　漢晉春秋曰：孫策之始得朗也，譴讓之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-25', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖問曰：「孫策何以得至此邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-014-26', 'p0191', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫策轉鬬千里，盡有江東，聞太祖與袁紹相持於官渡，將渡江北襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-014-27', 'p0191', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '又本傳稱嘉料孫策輕佻，必死於匹夫之手，誠為明於見事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-014-28', 'p0191', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫策惡之，遣使卑辭厚幣，以書說勳曰：「上繚宗民，數欺下國，忿之有年矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-015-29', 'p0191', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '後孫策所置廬江太守李述攻殺揚州刺史嚴象，廬江梅乾、雷緒、陳蘭等聚衆數萬在江、淮間，郡縣殘破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-022-30', 'p0191', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '避亂江東及東城，辭孫策、袁術之命，還本郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-022-31', 'p0191', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '避亂江東，又辭孫策之命，還本郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-035-32', 'p0191', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉繇、王朗各據州郡，論安言計，動引聖人，羣疑滿腹，衆難塞胷，今歲不戰，明年不征，使孫策坐大，遂并江東，此臣之未解二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-038-33', 'p0191', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孫策東渡江，皆走交州以避其難，靖身坐岸邊，先載附從，踈親悉發，乃從後去，當時見者莫不歎息。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-038-34', 'p0191', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖羇客會稽，閭閻之士，孫策之來，於靖何為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-046-35', 'p0191', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '初，吳郡太守許貢上表於漢帝曰：「孫策驍雄，與項籍相似，宜加貴寵，召還京邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-046-36', 'p0191', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫策雖威行江外，略有六郡，然黃祖乘其上流，陳登間其心腹，且深險彊宗未盡歸復，曹、袁虎爭，勢傾山海，策豈暇遠師汝、潁，而遷帝於吳、越哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-047-37', 'p0191', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '傅子曰：孫策為人明果獨斷，勇蓋天下，以父堅戰死，少而合其兵將以報讎，轉鬬千里，盡有江南之地，誅其名豪，威行鄰國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-049-38', 'p0191', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '漢命加繇為牧，振武將軍，衆數萬人，孫策東渡，破英、能等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-049-39', 'p0191', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '楊州刺史劉繇與慈同郡，慈自遼東還，未與相見，暫渡江到曲阿見繇，未去，會孫策至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-050-40', 'p0191', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫策與孫河、呂範依景，合衆共討涇縣山賊祖郎，郎敗走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-050-41', 'p0191', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '堅薨，隨孫策討樊能、于麋等於橫江，擊張英於當利口，而船少，欲駐軍更求。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-050-42', 'p0191', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '漢末，其母攜將徙廬江，廬江為孫策所破，皆東渡江，以美麗得幸於權，寵冠後庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-051-43', 'p0191', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫輔字國儀，賁弟也，以揚武校尉佐孫策平三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-051-44', 'p0191', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫策愛之，賜姓為孫，列之屬籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-051-45', 'p0191', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫策平定吳、會，誅其英豪，憲素有高名，策深忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-46', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫策創業，命昭為長史、撫軍中郎將，升堂拜母，如比肩之舊，文武之事，一以委昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-47', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫策蒞事日淺，恩澤未洽，一旦傾隕，士民狼狽，頗有同異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-48', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '典略曰：余曩聞劉荊州甞自作書欲與孫伯符，以示禰正平，正平蚩之，言：「如是為欲使孫策帳下兒讀之邪，將使張子布見乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-49', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '值孫策卒，孫權姊壻曲阿弘咨見而異之，薦之於權，與魯肅等並見賔待，後為權長史，轉中司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-053-50', 'p0191', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '初，紘同郡秦松字文表，陳端字子正，並與紘見待於孫策，參與謀謨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-053-51', 'p0191', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '評曰：張紘文理意正，為世令器，孫策待之亞於張昭，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-054-52', 'p0191', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '臣松之案：孫策于時始得豫章、廬陵，尚未能得定江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-054-53', 'p0191', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時孫策已薨，權尚住吳，瑜謂肅曰：「昔馬援荅光武云『當今之世，非但君擇臣，臣亦擇君』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-054-54', 'p0191', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '當為孫策將，數討山越。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-55', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '堅薨，復隨孫策在淮南，從攻廬江，拔之，還俱東渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-56', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '及孫策東渡，從討三郡，遷先登校尉，授兵二千，騎五十匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-57', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策之襲袁術，欽隨從給事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-58', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '與蔣欽隨孫策為左右，服事恭敬，數戰有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-59', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策在壽春，武往脩謁，時年十八，長七尺七寸，因從渡江，征討有功，拜別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-60', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策入郡，襲迎於高遷亭，策見而偉之，到署門下賊曹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-61', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '父操，輕俠有膽氣，孫策初興，每從征伐，常冠軍履鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-056-62', 'p0191', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '後避亂壽春，孫策見而異之，範遂自委昵，將私客百人歸策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-63', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策征會稽，翻時遭父喪，衰絰詣府門，朗欲就之，翻乃脫衰入見，勸朗避策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-64', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '翻未至豫章，聞孫策向會稽，翻乃還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-65', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '而傳云孫策之來，翻衰絰詣府門，勸朗避策，則為大異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-66', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '江表傳曰：策書謂翻曰：「今日之事，當與卿共之，勿謂孫策作郡吏相待也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-67', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '然王公拒戰，華逆請服，實由孫策初起，名微衆寡，故王能舉兵，豈武勝哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-68', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」因述孫策才略殊異，用兵之奇，歆乃荅云當去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-69', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策在吳，張昭、張紘、秦松為上賔，共論四海未泰，須當用武治而平之，績年少末坐，遙大聲言曰：「昔管夷吾相齊桓公，九合諸侯，一匡天下，不用兵車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-058-70', 'p0191', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '當禦備時，諸將軍或是孫策時舊將，或公室貴戚，各自矜恃，不相聽從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-058-71', 'p0191', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '抗字幼節，孫策外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-060-72', 'p0191', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安元年，孫策臨郡，察齊孝廉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-060-73', 'p0191', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫策到吳，柔舉兵先附，策表柔為丹楊都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-061-74', 'p0191', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '玄兄良，字文鸞，隨孫策平定江東，策以為會稽東部都尉，卒，玄領良兵，拜奮武中郎將，以功封溧陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-062-75', 'p0191', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '孫策領會稽太守，綜年十四，為門下循行，留吳與孫權共讀書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a05-015-76', 'p0191', 'jinshu', 'a05-015', '《晉書·卷十五》', '獻帝興平中，孫策分豫章立廬陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a05-037-77', 'p0191', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '自孫策至權，奕世相繼，惟強與弱，不在一禁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-009-0', 'p0192', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操以舟師伐孫權，權將周瑜敗之於烏林、赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-009-1', 'p0192', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十一月，孫權取荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-009-2', 'p0192', 'houhanshu', 'a03-009', '《後漢書·卷九》', '明年，劉備稱帝于蜀，孫權亦自王於吳，於是天下遂三分矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-070-3', 'p0192', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '及與孫權使語，謗訕朝廷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-070-4', 'p0192', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會南征孫權，表請彧勞軍于譙，因表留彧曰：「臣聞古之遣將，上設監督之重，下建副二之任，史記，齊景公以田穰苴為將軍，扞燕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-070-5', 'p0192', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '吳錄曰：「孫權聞操來，夾水立塢，狀如偃月，以相拒，月餘乃退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-072-6', 'p0192', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '溫參軍事孫堅說慎曰：堅字文臺，吳郡富春人，即孫權之父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-075-7', 'p0192', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫權破關羽，取荊州，以璋為益州牧，留住秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-075-8', 'p0192', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫策破勳，復見收視，術女入孫權宮，子曜仕吳為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-112-9', 'p0192', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '建安十三年，孫權分新都郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-112-10', 'p0192', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '建安十六年，孫權改曰建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-112-11', 'p0192', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '建安十五年，孫權分立鄱陽郡，治縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-113-12', 'p0192', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」　高涼建安二十五年，孫權立高梁郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-118-13', 'p0192', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '」獻帝春秋曰：「孫權以步隲行交州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-14', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十二月，孫權為備攻合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-15', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，孫權圍合肥，張遼、李典擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-16', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遂征孫權，十一月至譙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-17', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫權遣使上書，以討關羽自效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-18', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏略曰：孫權上書稱臣，稱說天命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-19', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '殿下應期，十分天下而有其九，以服事漢，羣生注望，遐邇怨歎，是故孫權在遠稱臣，此天人之應，異氣齊聲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-20', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋八月，孫權遣使奉章，并遣于禁等還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-21', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」魏書曰：癸亥，孫權上書，說：「劉備支黨四萬人，馬二三千匹，出秭歸，請往埽撲，以克捷為效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-22', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '五月，以荊、揚、江表八郡為荊州，孫權領牧故也；荊州江北諸郡為郢州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-23', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '閏月，孫權破劉備於夷陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-24', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏書載丙午詔曰：「孫權殘害民物，朕以寇不可長，故分命猛將三道並征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-25', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '論征孫權功，諸將已下進爵增戶各有差。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-26', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」三年之中，以孫權不服，復班太宗論於天下，明示不願征伐也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-27', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '胡沖吳歷曰：帝以素書所著典論及詩賦餉孫權，又以紙寫一通與張昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-28', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '八月，孫權攻江夏郡，太守文聘堅守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-29', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，公孫淵斬送孫權所遣使張彌、許晏首，以淵為大司馬樂浪公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-30', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權入居巢湖口，向合肥新城，又遣將陸議、孫韶各將萬餘人入淮、沔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-31', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '秋七月，高句驪王宮斬送孫權使胡衞等首，詣幽州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-32', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權遣將朱然等二萬人圍江夏郡，荊州刺史胡質等擊之，然退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-33', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '孫權自十數年以來，大畋江北，繕治甲兵，精其守禦，數出盜竊，敢遠其水，陸次平土，此中國所願聞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-34', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：初，孫權築東興隄以遏巢湖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-35', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '往者季漢分崩，九土顛覆，劉備、孫權乘間作禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-36', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '紹本偽南陵督，才質開壯；彧，孫權支屬，忠良見事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-006-37', 'p0192', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '術女入孫權宮，子燿拜郎中，燿女又配於權子奮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-008-38', 'p0192', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '淵遣使南通孫權，往來賂遺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-008-39', 'p0192', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '故公文下遼東，因赦之曰：「告遼東、玄菟將校吏民：逆賊孫權遭遇亂階，因其先人劫略州郡，遂成羣凶，自擅江表，含垢藏疾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-008-40', 'p0192', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '孫權慕義，不遠萬里，連年遣使，欲自結援，雖見絕殺，不念舊怨，纖纖往來，求成恩好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-41', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '二十一年，從征孫權還，使惇都督二十六軍，留居巢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-42', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征孫權還，使淵督諸將擊廬江叛者雷緒，緒破，又行征西護軍，督徐晃擊太原賊，攻下二十餘屯，斬賊帥商曜，屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-43', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '孫權遣將陳邵據襄陽，詔仁討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-44', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '孫權遣將屯歷陽，休到，擊破之，又別遣兵渡江，燒賊蕪湖營數千家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-45', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝征孫權，以休為征東大將軍，假黃鉞，督張遼等及諸州郡二十餘軍，擊權大將呂範等於洞浦，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-46', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '與夏侯尚等征孫權，擊牛渚屯，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-47', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '孫權雖稱藩，尚益脩攻討之備，權後果有貳心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-48', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會征孫權，表請彧勞軍于譙，因輒留彧，以侍中光祿大夫持節，參丞相軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-49', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧卒於壽春，壽春亡者告孫權，言太祖使彧殺伏后，彧不從，故自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-50', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荊人服劉主之雄姿，憚孫權之武略，為日旣乆，誠非曹氏諸將所能抗禦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-51', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '昔魏文帝用賈詡為三公，孫權笑之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-52', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '吳、蜀雖蕞爾小國，依岨山水，劉備有雄才，諸葛亮善治國，孫權識虛實，陸議見兵勢，據險守要，汎舟江湖，皆難卒謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-012-53', 'p0192', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」十三年，融對孫權使，有訕謗之言，坐棄市。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-012-54', 'p0192', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖征孫權，徙為留府長史，謂奕曰：「君之忠亮，古人不過也，然微太嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-55', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '魏略曰：孫權稱臣，斬送關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-56', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '』顧念孫權，了更侮媚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-57', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '至於荀公之清談，孫權之侮媚，執書嗢噱，不能離手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-58', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孫權欲不遣，歆謂權曰：「將軍奉王命，始交好曹公，分義未固，使僕得為將軍效心，豈不有益乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-59', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖征孫權，表歆為軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-60', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」太祖以孫權稱臣遣貢諮朗，朗荅曰：「孫權前牋，自詭躬討虜以補前愆，後疏稱臣，以明無二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-61', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '初，建安末，孫權始遣使稱藩，而與劉備交兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-62', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孫權欲遣子登入侍，不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-63', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '後孫權襲取其將士家屬，羽士衆一旦瓦解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-64', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '論者以為孫權必殺備，昱料之曰：「孫權新在位，未為海內所憚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-65', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及關羽圍曹仁於樊，孫權遣使辭以「遣兵西上，欲掩取羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-66', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：孫權遣使求降，帝以問曄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-67', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '建安十三年，孫權率衆圍合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-68', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備、孫權，外親內踈，關羽得志，權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-69', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」漢晉春秋曰：公孫淵聞魏將來討，復稱臣於孫權，乞兵自救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-70', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '帝問濟：「孫權其救遼東乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-71', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '青龍初，孫權與諸葛亮連和，欲俱出為寇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-72', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資別傳曰：是時，孫權、諸葛亮號稱劇賊，無歲不有軍征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-73', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '孫權率十萬衆攻圍合肥城百餘日，時天連雨，城欲崩，於是以苫蓑覆之，夜然脂照城外，視賊所作而為備，賊以破走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-74', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安二十四年，孫權攻合肥，是時諸州皆屯戍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-75', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '時孫權在東關，當豫州南，去江四百餘里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-76', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會病篤，謂左右曰：「受國厚恩，恨不斬孫權以下見先帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-77', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖旣征孫權還，使遼與樂進、李典等將七千餘人屯合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-78', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '俄而權率十萬衆圍合肥，乃共發教，教曰：「若孫權至者，張、李將軍出戰；樂將軍守，護軍勿得與戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-79', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安二十一年，太祖復征孫權，到合肥，循行遼戰處，歎息者良乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-80', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '孫權復叛，遣遼還屯合肥，進遼爵都鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-81', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '孫權復叛，帝遣遼乘舟，與曹休至海陵，臨江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-82', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '」會孫權禽羽，獲其衆，禁復在吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-83', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '明帝即位，遣南屯荊州，與司馬宣王擊孫權別將劉阿等，追至祁口，交戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-84', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與張遼、樂進屯合肥，孫權率衆圍之，遼欲奉教出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-85', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從討孫權，先登，再入巢湖，攻居巢，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-86', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '霸從討孫權於濡須口，與張遼為前鋒，行遇霖雨，大軍先及，水遂長，賊舩稍進，將士皆不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-87', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '而孫觀亦至青州刺史，假節，從太祖討孫權，戰被創，薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-88', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從征孫權於濡須口，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-89', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '孫權以五萬衆自圍聘於石陽，甚急，聘堅守不動，權住二十餘日乃解去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-90', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '魏略曰：孫權嘗自將數萬衆卒至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-019-91', 'p0192', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '太祖征孫權，使植留守鄴，戒之曰：「吾昔為頓丘令，年二十三。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-020-92', 'p0192', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '時孫權曾致巨象，太祖欲知其斤重，訪之羣下，咸莫能出其理。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-93', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '雄略冠時，智謀出世，摧袁氏於官渡，驅孫權於江外，逐劉備於隴右，破烏丸於白登，其餘梟夷蕩定者，往往如神，不可勝計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-94', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '臣松之案：孫權自此以前，尚與中國和同，未嘗交兵，何云「驅權於江外」乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-95', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今以海內之兵，百勝之威，而孫權負險於吳，劉備不賔於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-96', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時聞公孫淵受孫權燕王之號，議者欲留淵計吏，遣兵討之，劭以為「昔袁尚兄弟歸淵父康，康斬送其首，是淵先世之効忠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-97', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孫權自破關羽并荊州之後，志盈欲滿，凶宄以極，是以宣文侯深建宏圖大舉之策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-98', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '彪曰：嘉平四年四月，孫權死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-99', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孫權自破蜀兼平荊州之後，志盈欲滿，罪戮忠良，殊及胤嗣，元凶已極。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-100', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏議以為「淮海非賊輕行之路，又昔孫權遣兵入海，漂浪沈溺，略無孑遺，恪豈敢傾根竭本，寄命洪流，以徼乾沒乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-022-101', 'p0192', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '帝征孫權，至廣陵，使羣領中領軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-022-102', 'p0192', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '郡為孫權所圍於匡奇，登令矯求救於太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-022-103', 'p0192', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '征軍大將軍曹休表得降賊辭，「孫權已在濡須口」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-023-104', 'p0192', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '羽軍旣退，舟船猶據沔水，襄陽隔絕不通，而孫權襲取羽輜重，羽聞之，即走南還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-023-105', 'p0192', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '孫權寇邊，征東大將軍曹休統五州軍禦之，徵儼為軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-025-106', 'p0192', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '帝方脩殿舍，百姓勞役，毗上疏曰：「竊聞諸葛亮講武治兵，而孫權巿馬遼東，量其意指，似欲相左右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-107', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '孫權數擾東陲，復召寵還為汝南太守，賜爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-108', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '三年春，降人稱吳大嚴，揚聲欲詣江北獵，孫權欲自出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-109', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '其冬，孫權揚聲欲至合肥，寵表召兖、豫諸軍，皆集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-110', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '後孫權號十萬衆攻新城，征東將軍滿寵欲率諸軍救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-027-111', 'p0192', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '世語曰：黃初中，孫權通章表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-027-112', 'p0192', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '二年，昶奏：「孫權流放良臣，適庶分爭，可乘釁而制吳、蜀；白帝、夷陵之間，黔、巫、秭歸、房陵皆在江北，民夷與新城郡接，可襲取也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-027-113', 'p0192', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基曰：「昔孫權再至合肥，一至江夏，其後全琮出廬江，朱然寇襄陽，皆無功而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-028-114', 'p0192', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文帝踐阼，拜散騎常侍，出為兖州刺史，與張遼等至廣陵討孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-028-115', 'p0192', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾言景王曰：「孫權已沒，大臣未附，吳名宗大族，皆有部曲，阻兵仗勢，足以建命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-028-116', 'p0192', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，吳大將全琮，孫權之婚親重臣也，琮子懌、孫靜、從子端、翩、緝等，皆將兵來救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-031-117', 'p0192', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '孫權殺關羽，取荊州，以璋為益州牧，駐秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-118', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-119', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備大喜，進住鄂縣，即遣諸葛亮隨肅詣孫權，結同盟誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-120', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏書載劉備與孫權語，與蜀志述諸葛亮與權語正同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-121', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉備未破魏軍之前，尚未與孫權相見，不得有此說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-122', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：孫權欲與備共取蜀，遣使報備曰：「米賊張魯居王巴、漢，為曹操耳目，規圖益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-123', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '明年，曹公征孫權，權呼先主自救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-124', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '二十年，孫權以先主已得益州，使使報欲得荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-125', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '俄而孫權襲殺羽，取荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-126', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '初，先主忿孫權之襲關羽，將東征，秋七月，遂帥諸軍伐吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-127', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權遣書請和，先主盛怒不許，吳將陸議、李異、劉阿等屯巫、秭歸；將軍吳班、馮習自巫攻破異等，軍次秭歸，武陵五谿蠻夷遣使請兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-128', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權聞先主住白帝，甚懼，遣使請和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-033-129', 'p0192', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '遣尚書郎鄧芝固好於吳，吳王孫權與蜀和親使聘，是歲通好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-033-130', 'p0192', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '吳王孫權同恤灾患，潛軍合謀，掎角其後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-033-131', 'p0192', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，孫權稱帝，與蜀約盟，共交分天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-132', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '孫權據有江東，已歷三世，國險而民附，賢能為之用，此可與為援而不可圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-133', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '將軍旣帝室之胄，信義著於四海，總攬英雄，思賢如渴，若跨有荊、益，保其巖阻，西和諸戎，南撫夷越，外結好孫權，內脩政理；天下有變，則命一上將將荊州之軍以向宛、洛，將軍身率益州之衆出於秦川，百姓孰敢不簞食壺漿以迎將軍者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-134', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：張子布薦亮於孫權，亮不肯留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-135', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮聞孫權破曹休，魏兵東下，關中虛弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-136', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」漢晉春秋曰：是歲，孫權稱尊號，其羣臣以並尊二帝來告。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-137', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛氏集目錄                     　　開府作牧第一　　　權制第二                     　　南征第三　　　　　北出第四                   　　計筭第五　　　　　訓厲第六                   　　綜覈上第七　　　　綜覈下第八                   　　雜言上第九　　　　雜言下第十                   　　貴和第十一　　　　兵要第十二                   　　傳運第十三　　　　與孫權書第十四                   　　與諸葛瑾書第十五　與孟達書第十六                   　　廢李平第十七　　　法檢上第十八                   　　法檢下第十九　　　科令上第二十                   　　科令下第二十一　　軍令上第二十二                   　　軍令中第二十三　　軍令下第二十四                   　右二十四篇，凡十萬四千一百一十二字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-138', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮時年二十七，乃建奇策，身使孫權，求援吳會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-139', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '初，亮未有子，求喬為嗣，瑾啟孫權遣喬來西，亮以喬為己適子，故易其字焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-140', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '延熈十四年，以校尉使吳，值孫權病篤，不自見建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-141', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '孫權遣兵佐先主拒曹公，曹公引軍退歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-142', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公議徙許都以避其銳，司馬宣王、蔣濟以為關羽得志，孫權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-143', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '臣松之桉吳書：孫權遣將潘璋逆斷羽走路，羽至即斬，且臨沮去江陵二三百里，豈容不時殺羽，方議其生死乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-144', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '臨發，其帳下將張達、范彊殺飛，持其首，順流而奔孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-145', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '孫權襲荊州，先主大怒，欲討權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-146', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '雲諫曰：「國賊是曹操，非孫權也，且先滅魏，則吳自服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-037-147', 'p0192', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」亮荅曰：「主公之在公安也，北畏曹公之彊，東憚孫權之逼，近則懼孫夫人生變於肘腋之下；當斯之時，進退狼跋，法孝直為之輔翼，令翻然翱翔，不可復制，如何禁止法正使不得行其意邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-037-148', 'p0192', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」初，孫權以妹妻先主，妹才捷剛猛，有諸兄之風，侍婢百餘人，皆親執刀侍立，先主每入，衷心常凜凜；亮又知先主雅愛信正，故言如此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-037-149', 'p0192', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '先主旣即尊號，將東征孫權以復關羽之耻，羣臣多諫，一不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-038-150', 'p0192', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '芳為南郡太守，與關羽共事，而私好攜貳，叛迎孫權，羽因覆敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-038-151', 'p0192', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '遣東使於吳，孫權聞其才辯，欲逆折以辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-152', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：輔吳將軍張昭甞對孫權論巴褊阨，不當拒張飛太甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-153', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '七年，孫權稱尊號，以震為衞尉，賀權踐阼，諸葛亮與兄瑾書曰：「孝起忠純之性，老而益篤，及其贊述東西，歡樂和合，有可貴者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-154', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」震到武昌，孫權與震升壇歃盟，交分天下：以徐、豫、幽、青屬吳，并、涼、兾、兖屬蜀，其司州之土，以函谷關為界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-155', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '孫權甞大醉問禕曰：「楊儀、魏延，牧豎小人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-040-156', 'p0192', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕於獄中與諸葛亮書曰：「僕昔有事於諸侯，以為曹操暴虐，孫權無道，振威闇弱，其惟主公有霸王之器，可與興業致治，故乃翻然有輕舉之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-040-157', 'p0192', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-041-158', 'p0192', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先是，益州郡殺太守正昂，耆率雍闓恩信著於南土，使命周旋，遠通孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-044-159', 'p0192', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '孫權性旣滑稽，嘲啁無方，諸葛恪、羊衜等才愽果辯，論難鋒至，禕辭順義篤，據理以荅，終不能屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-044-160', 'p0192', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '禕別傳曰：孫權每別酌好酒以飲禕，視其已醉，然後問以國事，并論當世之務，辭難累至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-161', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '先是，吳王孫權請和，先主累遣宋瑋、費禕等與相報荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-162', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '孫權蓋謂丁厷之言多浮豔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-163', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '預將命使吳，孫權問預曰：「東之與西，譬猶一家，而聞西更增白帝之守，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-164', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '預復東聘吳，孫權捉預手，涕泣而別曰：「君每銜命結二國之好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-165', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」遺預大珠一斛，吳歷曰：預臨別，謂孫權曰：「蜀土僻小，雖云鄰國，東西相賴，吳不可無蜀，蜀不可無吳，君臣憑恃，唯陛下重垂神慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-166', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '士仁字君義，廣陽人也，為將軍，住公安，統屬關羽；與羽有隙，叛迎孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-167', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-046-168', 'p0192', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-169', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '公曰：「此必孫權欲身見吾軍部伍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-170', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」曹公語諸將曰：「孫權不欺孤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-171', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '吳王孫權，幼豎小子，無尺寸之功，遭遇兵亂，因父兄之緒，少蒙翼卵煦伏之恩，長含鴟梟反逆之性，背棄天施，罪惡積大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-172', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '孫權時合暮舉火於西陵，鼓三竟，達吳郡南沙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-173', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '評曰：孫權屈身忍辱，任才尚計，有句踐之奇英，人之傑矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-174', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '臣松之以為孫權橫廢無罪之子，雖為兆亂，然國之傾覆，自由暴皓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-048-175', 'p0192', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '臣松之案：孫權赤烏十年，詔徙武昌宮材瓦，以繕治建康宮，而此猶有端門內殿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-048-176', 'p0192', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳歷曰：亮數出中書視孫權舊事，問左右侍臣：「先帝數有特制，今大將軍問事，但令我書可邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-048-177', 'p0192', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '江表傳曰：定，汝南人，本孫權給使也，後出補吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-178', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '姿容美好，孫權愛敬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-179', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '孫權統事，以慈能制磐，遂委南方之事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-180', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '建安十五年，孫權遣步隲為交州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-181', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '呂岱師友士匡，使通信誓，徽兄弟肉袒，推心委命，岱因滅之，以要功利，君子是以知孫權之不能遠略，而呂氏之祚不延者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-050-182', 'p0192', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫權甞游幸諸營，而姬觀於道中，權望見異之，命宦者召入，以賜子和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-050-183', 'p0192', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '遠觀齊桓，近察孫權，皆有識士之明，傑人之志，而嫡庶不分，閨庭錯亂，遺笑古今，殃流後嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-051-184', 'p0192', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '初，孫權殺吳郡太守盛憲，會稽典錄曰：憲字孝章，器量雅偉，舉孝廉，補尚書郎，稍遷吳郡太守，以疾去官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-185', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權領會稽太守，不之郡，以雍為丞，行太守事，討除寇賊，郡界寧靜，吏民歸服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-186', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權統事，聞徽有才辯，召署主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-187', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為車騎將軍，辟西曹掾，轉主簿，出補海昏令，甚有惠化，年三十二卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-188', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '值孫策卒，孫權姊壻曲阿弘咨見而異之，薦之於權，與魯肅等並見賔待，後為權長史，轉中司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-189', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權潛包禍心，助魏除害，是為翦宗子勤王之師，行曹公移都之計，拯漢之規，於茲而止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-190', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」臣松之以為魏明帝一時明主，政自己出，孫權此論，竟為無徵，而史載之者，將以主幼國疑，威柄不一，亂亡之形，有如權言，宜其存錄以為鑒戒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-191', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為討虜將軍，召隲為主記，吳書曰：歲餘，隲以疾免，與琅邪諸葛瑾、彭城嚴畯俱游吳中，並著聲名，為當時英俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-192', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '獻帝春秋云：劉備至京，謂孫權曰：「吳去此數百里，即有驚急，赴救為難，將軍無意屯京乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-193', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '張昭進之於孫權，權以為騎都尉、從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-194', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孫權為驃騎將軍，辟補西曹掾；及稱尊號，以澤為尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-195', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '臣松之計孫權年大文帝五歲，其為長幼也微耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-196', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '士燮旣附孫權，召綜為五官中郎，除合浦、交阯太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-197', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」魏書及九州春秋曰：曹公征荊州，孫權大懼，魯肅實欲勸權拒曹公，乃激說權曰：「彼曹公者，實嚴敵也，新并袁紹，兵馬甚精，乘戰勝之威，伐喪亂之國，克可必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-198', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫盛曰：吳書及江表傳，魯肅一見孫權便說拒曹公而論帝王之略，劉表之死也，又請使觀變，無緣方復激說勸迎曹公也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-199', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-200', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權之論，優劣允當，故載錄焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-201', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策薨，與張昭等共輔孫權，遂周旋三郡，平討不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-202', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜、呂蒙皆共薦達，孫權加異，同於舊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-203', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-204', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫權統事，以為別部司馬，授兵五百人，守柴桑長，拒黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-205', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '干寶晉紀所云疑城，已注孫權傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-206', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫權為陽羨長，始往隨權。');
